  (4601, md5($bt$[{"phase":"education","start":null,"end":null,"title":"Pupil","organisation":"Market Place School, Inverurie","detail":"He attended Market Place School after moving to Inverurie.","source":{"title":"About Andrew","url":"https://www.andrewbowie.org.uk/about-andrew"}},{"phase":"education","start":null,"end":null,"title":"Pupil","organisation":"Inverurie Academy","detail":"He attended Inverurie Academy in Aberdeenshire.","source":{"title":"About Andrew","url":"https://www.andrewbowie.org.uk/about-andrew"}},{"phase":"education","start":null,"end":null,"title":"Member, National Youth Orchestra of Scotland","organisation":"National Youth Orchestra of Scotland","detail":"He played the violin in the National Youth Orchestra of Scotland during his school years.","source":{"title":"Andrew Bowie, politics.co.uk","url":"https://www.politics.co.uk/people/andrew-bowie/"}},{"phase":"education","start":"2007","end":null,"title":"Officer cadet","organisation":"Britannia Royal Naval College","detail":"He attended Britannia Royal Naval College after joining the Royal Navy in 2007.","source":{"title":"Andrew Bowie, politics.co.uk","url":"https://www.politics.co.uk/people/andrew-bowie/"}},{"phase":"education","start":null,"end":null,"title":"MA, History and Politics","organisation":"University of Aberdeen","detail":"He studied history and politics at the University of Aberdeen after leaving the Royal Navy, graduating with an MA.","source":{"title":"Andrew Bowie, politics.co.uk","url":"https://www.politics.co.uk/people/andrew-bowie/"}},{"phase":"education","start":null,"end":null,"title":"Member, Aberdeen University Royal Naval Unit","organisation":"University of Aberdeen","detail":"He was part of the Aberdeen University Royal Naval Unit while at university.","source":{"title":"Andrew Bowie, politics.co.uk","url":"https://www.politics.co.uk/people/andrew-bowie/"}},{"phase":"career","start":null,"end":null,"title":"Tobacco counter assistant","organisation":"Morrisons","de