ple/richard-holden/"}},{"phase":"career","start":"2002","end":"2006","title":"Waiter and bar staff","organisation":"Emporium Ltd, Clitheroe","detail":"He worked as a waiter and bar staff for Emporium Ltd in Clitheroe.","source":{"title":"Wikipedia: Richard Holden (British politician)","url":"https://en.wikipedia.org/wiki/Richard_Holden_(British_politician)"}},{"phase":"career","start":"2007-08","end":null,"title":"Data Entry Officer","organisation":"Conservative Campaign Headquarters","detail":"He started work at Conservative Campaign Headquarters in August 2007 as a data administrator.","source":{"title":"Class of 2019: Meet the new MPs, PoliticsHome","url":"https://www.politicshome.com/news/uk/political-parties/conservative-party/house/house-magazine/108577/class-2019-meet-new-mps"}},{"phase":"career","start":"2008","end":null,"title":"Media Monitoring Officer","organisation":"Conservative Campaign Headquarters","detail":"He became a media monitoring officer at Conservative Campaign Headquarters in 2008.","source":{"title":"Wikipedia: Richard Holden (British politician)","url":"https://en.wikipedia.org/wiki/Richard_Holden_(British_politician)"}},{"phase":"career","start":"2008","end":"2010","title":"Duty Press Officer","organisation":"Conservative Campaign Headquarters","detail":"He was a duty press officer at Conservative Campaign Headquarters.","source":{"title":"Wikipedia: Richard Holden (British politician)","url":"https://en.wikipedia.org/wiki/Richard_Holden_(British_politician)"}},{"phase":"career","start":"2010","end":"2012","title":"Political Press Adviser","organisation":"Conservative Campaign Headquarters","detail":"He was a political press adviser at Conservative Campaign Headquarters.","source":{"title":"Wikipedia: Richard Holden (British politician)","url":"https://en.wikipedia.org/wiki/Richard_Holden_(British_politician)"}},{"phase":"career","start":"2012","end":null,"title":"Deputy Head of Press","organisation":"Conservative Party","detail":"He beca