  (5285, md5($bt$[{"phase":"education","start":null,"end":null,"title":"Secondary education","organisation":"Guildford County School","detail":"She attended Guildford County School.","source":{"title":"Politics.co.uk: Katie Lam","url":"https://www.politics.co.uk/people/katie-lam/"}},{"phase":"education","start":null,"end":null,"title":"Classics degree","organisation":"Trinity College, Cambridge","detail":"She studied classics at Trinity College, Cambridge.","source":{"title":"Politics.co.uk: Katie Lam","url":"https://www.politics.co.uk/people/katie-lam/"}},{"phase":"education","start":null,"end":null,"title":"President of the Cambridge Union","organisation":"Cambridge Union","detail":"She was elected president of the Cambridge Union while at university.","source":{"title":"Politics.co.uk: Katie Lam","url":"https://www.politics.co.uk/people/katie-lam/"}},{"phase":"career","start":null,"end":null,"title":"Vice president","organisation":"Goldman Sachs","detail":"After graduating she worked at the investment bank Goldman Sachs for six years, reaching the position of vice president.","source":{"title":"Politics.co.uk: Katie Lam","url":"https://www.politics.co.uk/people/katie-lam/"}},{"phase":"career","start":null,"end":null,"title":"Lyricist and scriptwriter","organisation":null,"detail":"She is a lyricist and scriptwriter whose works have been performed in the West End and off Broadway.","source":{"title":"KentOnline: The former Boris Johnson aide picked for new Weald of Kent seat (5 September 2023)","url":"https://www.kentonline.co.uk/ashford/news/the-former-boris-aide-picked-for-new-kent-seat-rated-one-of-292860/"}},{"phase":"career","start":null,"end":null,"title":"Trustee","organisation":"Ivors Academy Trust","detail":"She was a trustee of the Ivors Academy Trust.","source":{"title":"Katie Lam for Weald of Kent: Meet Katie","url":"https://katieforkent.com/about-katie"}},{"phase":"career","start":"2019","end":"2020","title":"Special adviser, head of the Prime Ministe