DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography b JOIN bt_undo u USING (member_id) WHERE md5(b.background_timeline::text) = u.cur_md5) <> 25 THEN
    RAISE EXCEPTION 'a timeline is not the 2026-10-31e value (changed since)';
  END IF;
END $$;

UPDATE public.mp_biography b SET background_timeline = u.tl, background_last_checked = u.checked
  FROM bt_undo u WHERE b.member_id = u.member_id AND md5(b.background_timeline::text) = u.cur_md5;

DO $$
DECLARE
  changed integer;
  changed_outside integer;
  restored integer;
  with_timeline integer;
  entry_total integer;
BEGIN
  SELECT count(*) INTO changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO changed_outside FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id NOT IN (3912, 3948, 3969, 3991, 4399, 4462, 4474, 4503, 4513, 4519, 4527, 4601, 4613, 4679, 4759, 4780, 4813, 4874, 5285, 5297, 5311, 188, 632, 4038, 4077) AND md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO restored FROM public.mp_biography b JOIN bt_undo u USING (member_id)
   WHERE (u.old_md5 IS NULL AND b.background_timeline IS NULL AND b.background_last_checked IS NULL)
      OR (u.old_md5 IS NOT NULL AND md5(b.background_timeline::text) = u.old_md5 AND b.background_last_checked IS NOT DISTINCT FROM u.checked);
  SELECT count(*) INTO with_timeline FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  SELECT sum(jsonb_array_length(background_timeline)) INTO entry_total FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  RAISE NOTICE 'UNDO: rows changed %, outside the 25 %, restored %, MPs with a timeline %, entries %', changed, changed_outside, restored, with_timeline, entry_total;
  IF changed <> 25 THEN RAISE EXCEPTION 'expected exactly 25 rows changed, got %', changed; END IF;
  IF changed_outside <> 0 THEN RAISE EXCEPTION '% rows outside the 25 changed', changed_outside; END IF;
  IF restored <> 25 THEN RAISE EXCEPTION 'expected 25 rows restored, got %', restored; END IF;
  IF with_timeline <> 49 THEN RAISE EXCEPTION 'expected 49 MPs with a timeline, got %', with_timeline; END IF;
  IF entry_total <> 639 THEN RAISE EXCEPTION 'expected 639 entries, got %', entry_total; END IF;
END $$;

COMMIT;
